// stlport
//
// vector<ModuleInfo::Nugget>::push_back, retail 0x00119EC0 (55 B).
// Same STLport emission recipe as AsciiStringVectorPushBackEmit.cpp: the
// address-of-pointer definition forces the out-of-line push_back COMDAT. The
// 0x74 element size is BFME2's ModuleInfo::Nugget (refcounted name header plus
// four 28-byte blocks); _Construct<Nugget> is the rowed body at 0x00119B30 and
// the overflow path calls the unrowed _M_insert_overflow<Nugget> at 0x00119D80,
// declared through the STLport header and pinned.

// Retail keeps one unsigned max, RVA 0x00013740 (the vendored STLport row). This unit's
// flags (/G7 /arch:SSE) compile a different copy, and retail kept another unit's. This unit-local
// overload keeps the inlined code and offers the link no second copy.
#include <stl/_algobase.h>
namespace _STL {
static inline const unsigned int &max(const unsigned int &a, const unsigned int &b)
{
    return a < b ? b : a;
}
}

#include <vector>

struct NuggetString
{
	struct Header
	{
		int m_unreconstructed_00;
		unsigned short refCount;
	};
	Header *m_data;

	NuggetString(const NuggetString &that)
		: m_data(that.m_data)
	{
		if (m_data)
			m_data->refCount += 1;
	}
};

struct NuggetBlock
{
	int m_words[7];
};

class ModuleInfo
{
public:
	struct Nugget
	{
		Nugget(const Nugget &that);

		NuggetString name;
		NuggetBlock a;
		NuggetBlock b;
		NuggetBlock c;
		NuggetBlock d;
	};
};

inline ModuleInfo::Nugget::Nugget(const Nugget &that)
	: name(that.name),
	  a(that.a),
	  b(that.b),
	  c(that.c),
	  d(that.d)
{
}

extern void (_STL::vector<ModuleInfo::Nugget>::*const g_bfmeNuggetVectorPushBack)(const ModuleInfo::Nugget &);
void (_STL::vector<ModuleInfo::Nugget>::*const g_bfmeNuggetVectorPushBack)(const ModuleInfo::Nugget &) =
	&_STL::vector<ModuleInfo::Nugget>::push_back;
